-- Casos de portafolio. El texto vive en copy { es, en }. Las maquetas se eligen una sola vez.
-- Lectura pública. Escritura solo con app_metadata.role = admin.

create table public.projects (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  date text not null,
  display_order integer not null,
  featured boolean not null default false,
  anonymized boolean not null default false,
  hero text not null,
  tags text[] not null default '{}',
  screens jsonb not null,
  copy jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint projects_slug_format
    check (char_length(slug) between 1 and 80 and slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  constraint projects_date_format
    check (date ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  constraint projects_display_order_range
    check (display_order between 0 and 9999),
  constraint projects_display_order_unique
    unique (display_order) deferrable initially deferred,
  constraint projects_hero_known
    check (hero in ('tarifas-hero', 'tarifas-config', 'tarifas-ahorro', 'agpe-hero', 'agpe-liquidacion', 'agpe-xm', 'saidi-hero', 'saidi-pasos', 'saidi-consolidado', 'mem-hero', 'mem-descarga', 'mem-proceso', 'aenc-hero', 'aenc-registro', 'aenc-versiones', 'radar-hero', 'radar-senal', 'radar-historial')),
  constraint projects_tags_limit
    check (cardinality(tags) <= 12),
  constraint projects_screens_shape
    check (
      jsonb_typeof(screens) = 'array'
      and jsonb_array_length(screens) = 2
      and jsonb_typeof(screens -> 0) = 'object'
      and jsonb_typeof(screens -> 1) = 'object'
      and (screens -> 0 ->> 'mock') in ('tarifas-hero', 'tarifas-config', 'tarifas-ahorro', 'agpe-hero', 'agpe-liquidacion', 'agpe-xm', 'saidi-hero', 'saidi-pasos', 'saidi-consolidado', 'mem-hero', 'mem-descarga', 'mem-proceso', 'aenc-hero', 'aenc-registro', 'aenc-versiones', 'radar-hero', 'radar-senal', 'radar-historial')
      and (screens -> 1 ->> 'mock') in ('tarifas-hero', 'tarifas-config', 'tarifas-ahorro', 'agpe-hero', 'agpe-liquidacion', 'agpe-xm', 'saidi-hero', 'saidi-pasos', 'saidi-consolidado', 'mem-hero', 'mem-descarga', 'mem-proceso', 'aenc-hero', 'aenc-registro', 'aenc-versiones', 'radar-hero', 'radar-senal', 'radar-historial')
    ),
  constraint projects_copy_locale
    check (
      jsonb_typeof(copy) = 'object'
      and (
        (copy ? 'es' and jsonb_typeof(copy -> 'es') = 'object')
        or (copy ? 'en' and jsonb_typeof(copy -> 'en') = 'object')
      )
    )
);

create index projects_display_order_idx on public.projects (display_order);

create trigger trg_projects_set_updated_at
before update on public.projects
for each row execute function public.set_updated_at();

alter table public.projects enable row level security;

revoke all on table public.projects from anon, authenticated;
grant select on table public.projects to anon, authenticated;
grant insert, update, delete on table public.projects to authenticated;

do $sequence_grants$
declare
  projects_sequence text;
begin
  projects_sequence := pg_get_serial_sequence('public.projects', 'id');
  if projects_sequence is not null then
    execute format('revoke all on sequence %s from anon', projects_sequence);
    execute format('revoke all on sequence %s from authenticated', projects_sequence);
    execute format('grant usage, select on sequence %s to authenticated', projects_sequence);
  end if;
end
$sequence_grants$;

create policy "projects_public_read"
on public.projects
for select
to anon, authenticated
using (true);

create policy "projects_admin_insert"
on public.projects
for insert
to authenticated
with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');

create policy "projects_admin_update"
on public.projects
for update
to authenticated
using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin')
with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');

create policy "projects_admin_delete"
on public.projects
for delete
to authenticated
using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');

comment on table public.projects is
  'Portfolio cases. Anonymous users can read; only users with app_metadata.role=admin can write.';

insert into public.projects (
  slug, date, display_order, featured, anonymized, hero, tags, screens, copy
) values (
  'comparador-tarifas-energia',
  '2025-03',
  0,
  true,
  true,
  'tarifas-hero',
  array['Python', 'Streamlit', 'Azure AD', 'SharePoint']::text[],
  $screens_0$[{"mock":"tarifas-config"},{"mock":"tarifas-ahorro"}]$screens_0$::jsonb,
  $copy_0${"es":{"title":"Comparador de Tarifas de Energía","excerpt":"Compara el costo unitario de una comercializadora frente a sus competidores y proyecta el ahorro de un cliente en minutos.","lead":"Una herramienta web a la medida que convierte una comparación manual de tarifas en un análisis automático, trazable y listo para presentar al cliente.","facts":[{"label":"Tipo","value":"Aplicación web interna, software a la medida"},{"label":"Rol","value":"Diseño, desarrollo y puesta en producción"},{"label":"Estado","value":"En producción, en evolución continua"},{"label":"Usuarios","value":"Equipo comercial (más de 10 ejecutivos)"},{"label":"Stack","value":"Python, Streamlit, Pandas, Plotly, openpyxl"},{"label":"Integraciones","value":"Azure AD (OAuth2) y SharePoint vía Microsoft Graph"}],"summary":["La aplicación permite al equipo comercial de una comercializadora de energía comparar su Costo Unitario (CU) frente al de otros comercializadores del mercado, cuantificar el ahorro proyectado para un cliente y exportar el resultado como soporte de una oferta.","Los datos se leen directamente de la fuente oficial en SharePoint, el análisis aplica una lógica de comparación propia del negocio energético y el resultado se presenta en un tablero con la identidad visual de la empresa."],"context":{"paragraphs":["En el mercado de energía no regulada, la principal palanca comercial es demostrar con cifras que el costo propio es más competitivo que el de la competencia a lo largo del tiempo. La comparación no es trivial: el CU cambia cada mes y depende del mercado, del nivel de tensión y del comercializador.","Comparar un solo mes puede engañar: un competidor puede tener un mes puntual más barato y aun así ser más costoso en el acumulado. Además, la información viva reside en un libro de Excel corporativo, y trabajar sobre copias locales generaba inconsistencias y riesgo de usar datos desactualizados."],"question":"¿Cuánto habría ahorrado este cliente en los últimos meses y en qué periodos fuimos realmente más competitivos?"},"novelty":"No existe un producto comercial que resuelva la comparación de CU con esta lógica: por mercado y nivel de tensión, con promedios acumulados periodo a periodo y proyección de ahorro sobre el consumo real del cliente, integrado a la infraestructura corporativa.","challenges":[{"title":"Algoritmo de comparación por promedio acumulado","text":"Recorre los periodos del más reciente hacia atrás y evalúa el promedio acumulado del CU propio frente al del competidor. Cada periodo se clasifica como Exitoso o de Atención, y los periodos que no existen en ambos comercializadores se concilian para comparar sobre una base homogénea."},{"title":"Lectura validada de la fuente corporativa","text":"La fuente es una tabla nombrada dentro de un Excel en SharePoint. La lectura valida el esquema de columnas antes de procesar, de modo que si la estructura cambia el análisis falla con un mensaje claro en lugar de producir resultados erróneos en silencio."},{"title":"Inicio de sesión corporativo en un entorno restringido","text":"OAuth2 sobre Azure AD dentro de las restricciones de aislamiento de marcos de la plataforma. La solución es un flujo de ventana emergente que se autentica, se cierra sola y deja la sesión lista. Fue el componente que más pruebas requirió."},{"title":"Sistema de diseño sobre un framework cerrado","text":"Paleta, tipografía, tarjetas, indicadores y tablas reutilizables sobre Streamlit, que no está pensado para ese nivel de personalización. Incluye técnicas propias para estilizar componentes que el framework no deja tocar directamente."}],"method":["Arquitectura por capas: la lógica de negocio son funciones puras, separadas de la interfaz.","Funciones con contrato explícito: devuelven resultado y mensaje de error, y la interfaz decide cómo comunicarlo.","Configuración externalizada y validada al arrancar, sin credenciales en el código.","Git desde el primer commit y documentación técnica junto al código."],"stack":[{"label":"Python 3","value":"Núcleo de la aplicación"},{"label":"Streamlit","value":"Interfaz de usuario y servidor"},{"label":"Pandas","value":"Transformación y cálculo sobre los datos"},{"label":"Plotly","value":"Gráficos interactivos de comparación"},{"label":"openpyxl","value":"Extracción de la tabla de origen y exportación"},{"label":"Azure AD · Graph API","value":"Autenticación y descarga desde SharePoint"}],"architecture":[{"label":"app.py","value":"Punto de entrada: validación, autenticación y enrutamiento"},{"label":"auth/","value":"Azure AD y cliente de SharePoint"},{"label":"config/","value":"Constantes, validación y estilos"},{"label":"ui/","value":"Tablero, carga, comparación y ahorro"},{"label":"utils/","value":"Lógica de negocio pura"}],"flow":["Valida la configuración al arrancar.","Autentica al usuario contra Azure AD.","Descarga el archivo de tarifas de SharePoint con los permisos del usuario.","Lee y valida la tabla, normaliza tipos y ordena.","El usuario elige mercado, comercializadores, nivel de tensión y rango de periodos.","El algoritmo calcula y clasifica cada periodo.","Presenta el tablero, el gráfico y el ahorro, con exportación a Excel."],"features":[{"title":"Carga automática desde SharePoint","text":"Resume el universo de datos disponible y garantiza el uso del dato oficial."},{"title":"Comparación multi-competidor","text":"La comercializadora propia frente a hasta tres competidores a la vez."},{"title":"Clasificación por periodo","text":"Cada periodo queda marcado como Exitoso o de Atención según el promedio acumulado."},{"title":"Gráfico interactivo","text":"Evolución del CU, clara para presentarla al cliente."},{"title":"Ahorro proyectado","text":"Ahorro absoluto, porcentual y mensual a partir del consumo del cliente, con la fórmula a la vista."},{"title":"Exportación a Excel","text":"Un archivo por comercializador comparado, como soporte de la oferta."}],"screens":[{"title":"Configuración y periodo a periodo","caption":"Se elige el mercado, los competidores y el rango; la tabla marca cada periodo como Exitoso o de Atención."},{"title":"Ahorro proyectado","caption":"Con el consumo del cliente se calcula el ahorro del periodo y se muestra la fórmula, de modo que el resultado se puede auditar."}],"impact":{"stats":[{"value":"~3 min","label":"por comparación, antes ~1 h"},{"value":"4–8","label":"análisis al día"},{"value":"+10","label":"ejecutivos usuarios"},{"value":"~10 mil","label":"registros de tarifas procesados"}],"rows":[{"indicator":"Tiempo de una comparación","before":"~1 hora, manual en Excel","after":"~3 minutos"},{"indicator":"Fuente de datos","before":"Copias locales, riesgo de desactualización","after":"Dato oficial y vigente desde SharePoint"},{"indicator":"Consistencia del análisis","before":"Variable según el analista","after":"Lógica única y estandarizada"}],"closing":"Convirtió un análisis disperso y manual en un argumento de venta cuantificado y verificable, alineado con la infraestructura corporativa y con una presentación a la altura de una oferta comercial."}},"en":{"title":"Energy Tariff Comparator","excerpt":"Compares a retailer's unit cost against its competitors and projects a customer's savings in minutes.","lead":"A custom-built web tool that turns a manual tariff comparison into an automatic, traceable analysis, ready to present to the customer.","facts":[{"label":"Type","value":"Internal web application, custom software"},{"label":"Role","value":"Design, development, and production rollout"},{"label":"Status","value":"In production, continuously evolving"},{"label":"Users","value":"Sales team (more than 10 executives)"},{"label":"Stack","value":"Python, Streamlit, Pandas, Plotly, openpyxl"},{"label":"Integrations","value":"Azure AD (OAuth2) and SharePoint via Microsoft Graph"}],"summary":["The application lets an energy retailer's sales team compare its Unit Cost (CU) against that of other retailers in the market, quantify the projected savings for a customer, and export the result as support for an offer.","The data is read directly from the official source in SharePoint, the analysis applies a comparison logic specific to the energy business, and the result is presented on a dashboard with the company's visual identity."],"context":{"paragraphs":["In the non-regulated energy market, the main commercial lever is to show with figures that one's own cost is more competitive than the competition's over time. The comparison is not trivial: the CU changes every month and depends on the market, the voltage level, and the retailer.","Comparing a single month can be misleading: a competitor may have one cheaper month and still be more expensive in the cumulative total. In addition, the live information lives in a corporate Excel workbook, and working from local copies created inconsistencies and the risk of using outdated data."],"question":"How much would this customer have saved in recent months, and in which periods were we actually more competitive?"},"novelty":"There is no commercial product that solves CU comparison with this logic: by market and voltage level, with cumulative averages period by period and a savings projection based on the customer's actual consumption, integrated with the corporate infrastructure.","challenges":[{"title":"Cumulative-average comparison algorithm","text":"It walks the periods from the most recent backward and evaluates the cumulative average of one's own CU against the competitor's. Each period is classified as Successful or Attention, and periods that do not exist for both retailers are reconciled so the comparison rests on a homogeneous base."},{"title":"Validated read of the corporate source","text":"The source is a named table inside an Excel file in SharePoint. The read validates the column schema before processing, so if the structure changes the analysis fails with a clear message instead of silently producing wrong results."},{"title":"Corporate sign-in in a restricted environment","text":"OAuth2 over Azure AD within the platform's frame-isolation restrictions. The solution is a popup flow that authenticates, closes itself, and leaves the session ready. It was the component that required the most testing."},{"title":"Design system on a closed framework","text":"Palette, typography, cards, indicators, and reusable tables on Streamlit, which is not designed for that level of customization. It includes custom techniques for styling components the framework does not let you touch directly."}],"method":["Layered architecture: the business logic is pure functions, separated from the interface.","Functions with an explicit contract: they return a result and an error message, and the interface decides how to communicate it.","Configuration externalized and validated at startup, with no credentials in the code.","Git from the first commit and technical documentation alongside the code."],"stack":[{"label":"Python 3","value":"Application core"},{"label":"Streamlit","value":"User interface and server"},{"label":"Pandas","value":"Transformation and calculation on the data"},{"label":"Plotly","value":"Interactive comparison charts"},{"label":"openpyxl","value":"Extraction of the source table and export"},{"label":"Azure AD · Graph API","value":"Authentication and download from SharePoint"}],"architecture":[{"label":"app.py","value":"Entry point: validation, authentication, and routing"},{"label":"auth/","value":"Azure AD and SharePoint client"},{"label":"config/","value":"Constants, validation, and styles"},{"label":"ui/","value":"Dashboard, load, comparison, and savings"},{"label":"utils/","value":"Pure business logic"}],"flow":["Validates the configuration at startup.","Authenticates the user against Azure AD.","Downloads the tariff file from SharePoint with the user's permissions.","Reads and validates the table, normalizes types, and sorts.","The user chooses the market, the retailers, the voltage level, and the period range.","The algorithm calculates and classifies each period.","Presents the dashboard, the chart, and the savings, with export to Excel."],"features":[{"title":"Automatic load from SharePoint","text":"Summarizes the available data universe and guarantees use of the official data."},{"title":"Multi-competitor comparison","text":"The company's own retailer against up to three competitors at once."},{"title":"Classification by period","text":"Each period is marked Successful or Attention according to the cumulative average."},{"title":"Interactive chart","text":"CU evolution, clear enough to present to the customer."},{"title":"Projected savings","text":"Absolute, percentage, and monthly savings from the customer's consumption, with the formula in view."},{"title":"Export to Excel","text":"One file per compared retailer, as support for the offer."}],"screens":[{"title":"Configuration and period by period","caption":"The market, the competitors, and the range are chosen; the table marks each period as Successful or Attention."},{"title":"Projected savings","caption":"From the customer's consumption, the period's savings are calculated and the formula is shown, so the result can be audited."}],"impact":{"stats":[{"value":"~3 min","label":"per comparison, previously ~1 h"},{"value":"4–8","label":"analyses per day"},{"value":"+10","label":"executive users"},{"value":"~10 mil","label":"tariff records processed"}],"rows":[{"indicator":"Time for one comparison","before":"~1 hour, manual in Excel","after":"~3 minutes"},{"indicator":"Data source","before":"Local copies, risk of outdated data","after":"Official, current data from SharePoint"},{"indicator":"Consistency of the analysis","before":"Varies by analyst","after":"Single, standardized logic"}],"closing":"It turned a scattered, manual analysis into a quantified, verifiable sales argument, aligned with the corporate infrastructure and with a presentation worthy of a commercial offer."}}}$copy_0$::jsonb
);

insert into public.projects (
  slug, date, display_order, featured, anonymized, hero, tags, screens, copy
) values (
  'liquidacion-agpe',
  '2026-01',
  1,
  true,
  true,
  'agpe-hero',
  array['Python', 'Pandas', 'Excel', 'Regulación CREG']::text[],
  $screens_1$[{"mock":"agpe-liquidacion"},{"mock":"agpe-xm"}]$screens_1$::jsonb,
  $copy_1${"es":{"title":"Liquidación AGPE","excerpt":"Liquida a los autogeneradores a pequeña escala según la regulación colombiana y genera el reporte al mercado y el anexo de factura.","lead":"Cálculo regulatorio hora a hora, reporte en formato oficial y anexo por usuario, automatizados de extremo a extremo.","facts":[{"label":"Tipo","value":"Aplicación web interna, software a la medida"},{"label":"Rol","value":"Diseño, desarrollo y puesta en producción"},{"label":"Estado","value":"En producción, uso mensual"},{"label":"Usuarios","value":"Áreas de facturación y operaciones comerciales"},{"label":"Marco","value":"Resolución CREG 174 de 2021, artículo 26"},{"label":"Stack","value":"Python, Streamlit, Pandas, openpyxl, MSAL"},{"label":"Despliegue","value":"Azure App Service"}],"summary":["Automatiza la liquidación de la energía de los usuarios con Autogeneración a Pequeña Escala (AGPE). Toma las lecturas horarias de energía importada y exportada, calcula los excedentes de tipo 1 y tipo 2 hora a hora, los valora según la tarifa del periodo y el precio de bolsa, y produce la liquidación económica de cada usuario.","Con el mismo cálculo genera el archivo regulatorio en el formato exacto que exige el operador del mercado y el anexo de energía que se adjunta a la factura de cada usuario."],"context":{"paragraphs":["Un usuario AGPE entrega sus excedentes a la red y recibe una compensación. La regulación divide esos excedentes en dos tipos con reglas de valoración distintas, y la separación no es un total mensual: se resuelve hora a hora, acumulando cronológicamente hasta alcanzar la energía que el usuario importó.","El excedente tipo 2 se valora al precio de bolsa, que cambia cada hora de cada día. Además, el mercado exige un archivo con formato estricto y la factura de cada usuario debe llevar su matriz horaria. Hacerlo a mano para cientos de usuarios y 24 horas por día es inviable de forma confiable."],"question":"¿Cuánto se le debe pagar o cobrar a cada usuario este mes, según la fórmula regulatoria, y cómo lo entregamos en el formato exacto que exige el mercado?"},"novelty":"No existe un producto comercial que aplique esta regla: separación de excedentes por llenado horario cronológico, valoración diferenciada por costo unitario y por precio de bolsa horario, y generación del archivo oficial, integrado a la infraestructura corporativa.","challenges":[{"title":"Separación horaria de excedentes tipo 1","text":"Recorre la energía exportada en orden cronológico y acumula hora a hora hasta alcanzar el tope importado. En la hora exacta en que se alcanza, parte la casilla y asigna solo la fracción que falta. No se resuelve con una suma ni con un mínimo mensual."},{"title":"Excedente tipo 2 por diferencia condicionada","text":"Compara la matriz de tipo 1 contra la exportada original con tres casos por casilla: antes del tope es cero, en la hora del cruce es la diferencia y después del tope es todo lo exportado. Encadenar ese estado durante todo el mes exigió mucha verificación."},{"title":"Archivo regulatorio con layout estricto","text":"Layout de salida propio con 24 columnas horarias, mapeo de fuentes de energía a los códigos oficiales, normalización de identificadores y convenciones de formato fijas, con validaciones y advertencias cuando falta un insumo."},{"title":"Anexo por usuario sobre una plantilla Excel","text":"Genera un libro con una hoja por usuario clonando la plantilla: preserva el formato heredado, escribe sobre celdas combinadas, ajusta el rango de la tabla nombrada y limpia las filas sobrantes, para que cada anexo salga impecable."},{"title":"Escritura segura de vuelta en SharePoint","text":"La aplicación también escribe: crea de forma idempotente la estructura de carpetas por año y mes y sube el archivo generado, con manejo diferenciado de errores de permisos. El inicio de sesión usa un estado firmado con expiración contra CSRF."}],"method":["La fórmula regulatoria vive en funciones puras y verificables, aparte de la interfaz.","Detección preventiva de fechas duplicadas: se informa antes de liquidar, no después.","Lectura de tablas nombradas recorriendo todas las hojas del libro de origen.","Versionado en Git y documentación mantenida junto al código."],"stack":[{"label":"Python 3","value":"Núcleo de la aplicación"},{"label":"Streamlit","value":"Interfaz y servidor"},{"label":"Pandas","value":"Cálculo horario de excedentes y liquidación"},{"label":"openpyxl","value":"Tablas nombradas y exportación con formato"},{"label":"MSAL · OAuth2","value":"Inicio de sesión corporativo"},{"label":"Graph API · Azure","value":"Lectura y escritura en SharePoint, despliegue"}],"architecture":[{"label":"app.py","value":"Orquestador y enrutador de los tres módulos"},{"label":"auth/","value":"Azure AD y cliente de SharePoint"},{"label":"ui/","value":"Liquidación, impresión de matrices y archivo del mercado"},{"label":"utils/","value":"Liquidación, matrices, exportación y generador del archivo"}],"flow":["Carga tarifas, usuarios, precios de bolsa y matrices desde SharePoint.","Valida la integridad: fechas duplicadas por usuario y tipo de energía.","Resume la energía por usuario antes de liquidar.","Genera la matriz de excedentes tipo 1 y luego la de tipo 2.","Liquida por usuario: valoración del excedente, contribución, alumbrado y total.","Exporta a Excel, imprime las matrices y publica el archivo del mercado en SharePoint."],"features":[{"title":"Liquidación por usuario","text":"Valoración del excedente, contribución, alumbrado público y total a pagar, de forma auditable."},{"title":"Matrices Exc1 y Exc2","text":"Generación hora a hora con el resumen de energía por usuario."},{"title":"Impresión de matrices","text":"Una hoja por usuario sobre plantilla corporativa, con barra de progreso para lotes grandes."},{"title":"Archivo del mercado","text":"Generado en el formato oficial y publicado en SharePoint por año y mes."},{"title":"Validación de integridad","text":"Evita liquidaciones erróneas por datos de origen inconsistentes."},{"title":"Exportación con formato","text":"Todas las tablas a Excel con formato de moneda."}],"screens":[{"title":"Liquidación por usuario","caption":"Resumen del periodo y tabla con la valoración del excedente y el total a pagar de cada usuario."},{"title":"Archivo del mercado y anexo","caption":"Generación del archivo oficial con su vista previa y de las hojas por usuario para la factura."}],"impact":{"stats":[{"value":"~5 min","label":"por liquidación, antes más de 12 h"},{"value":"~3 min","label":"para las matrices, antes más de 5 h"},{"value":"~250","label":"usuarios liquidados por periodo"},{"value":"3","label":"salidas: liquidación, reporte y anexo"}],"rows":[{"indicator":"Liquidación de un periodo","before":"Más de 12 horas, manual en Excel","after":"~5 minutos"},{"indicator":"Matrices horarias por usuario","before":"Más de 5 horas, propensas a errores","after":"~3 minutos, formato uniforme"},{"indicator":"Cálculo hora a hora","before":"Errores de arrastre","after":"Automático y consistente"},{"indicator":"Archivo para el mercado","before":"Manual, riesgo de rechazo","after":"Formato exacto, generado"}],"closing":"Cubre de extremo a extremo las tres salidas del proceso: la liquidación económica, el reporte al mercado y el documento que ve el cliente. Redujo el riesgo de error y estandarizó un proceso que dependía del cuidado manual de cada analista."}},"en":{"title":"AGPE Settlement","excerpt":"Settles small-scale self-generators under Colombian regulation and generates the market report and the invoice annex.","lead":"Hour-by-hour regulatory calculation, a report in the official format, and a per-user annex, automated end to end.","facts":[{"label":"Type","value":"Internal web application, custom software"},{"label":"Role","value":"Design, development, and production rollout"},{"label":"Status","value":"In production, monthly use"},{"label":"Users","value":"Billing and commercial operations areas"},{"label":"Framework","value":"CREG Resolution 174 of 2021, article 26"},{"label":"Stack","value":"Python, Streamlit, Pandas, openpyxl, MSAL"},{"label":"Deployment","value":"Azure App Service"}],"summary":["It automates the energy settlement for users with Small-Scale Self-Generation (AGPE). It takes the hourly readings of imported and exported energy, calculates type 1 and type 2 surpluses hour by hour, values them according to the period tariff and the spot price, and produces each user's economic settlement.","With the same calculation it generates the regulatory file in the exact format the market operator requires and the energy annex attached to each user's invoice."],"context":{"paragraphs":["An AGPE user delivers their surplus to the grid and receives compensation. The regulation divides those surpluses into two types with different valuation rules, and the split is not a monthly total: it is resolved hour by hour, accumulating chronologically until the energy the user imported is reached.","Type 2 surplus is valued at the spot price, which changes every hour of every day. In addition, the market requires a file with a strict format, and each user's invoice must carry their hourly matrix. Doing it by hand for hundreds of users and 24 hours a day cannot be done reliably."],"question":"How much should each user be paid or charged this month, according to the regulatory formula, and how do we deliver it in the exact format the market requires?"},"novelty":"There is no commercial product that applies this rule: surplus separation by chronological hourly fill, differentiated valuation by unit cost and by hourly spot price, and generation of the official file, integrated with the corporate infrastructure.","challenges":[{"title":"Hourly separation of type 1 surpluses","text":"It walks the exported energy in chronological order and accumulates hour by hour until the imported cap is reached. In the exact hour it is reached, it splits the cell and assigns only the missing fraction. It is not solved with a sum or with a monthly minimum."},{"title":"Type 2 surplus by conditional difference","text":"It compares the type 1 matrix against the original exported matrix with three cases per cell: before the cap it is zero, in the crossing hour it is the difference, and after the cap it is everything exported. Chaining that state across the whole month required extensive verification."},{"title":"Regulatory file with a strict layout","text":"A custom output layout with 24 hourly columns, a mapping of energy sources to the official codes, identifier normalization, and fixed format conventions, with validations and warnings when an input is missing."},{"title":"Per-user annex on an Excel template","text":"It generates a workbook with one sheet per user by cloning the template: it preserves the inherited formatting, writes over merged cells, adjusts the named table's range, and clears leftover rows, so each annex comes out clean."},{"title":"Safe write-back to SharePoint","text":"The application also writes: it idempotently creates the year-and-month folder structure and uploads the generated file, with differentiated handling of permission errors. Sign-in uses a signed state with an expiration against CSRF."}],"method":["The regulatory formula lives in pure, verifiable functions, apart from the interface.","Preventive detection of duplicate dates: they are reported before settling, not after.","Reading of named tables by walking every sheet of the source workbook.","Versioned in Git and documentation kept alongside the code."],"stack":[{"label":"Python 3","value":"Application core"},{"label":"Streamlit","value":"Interface and server"},{"label":"Pandas","value":"Hourly surplus calculation and settlement"},{"label":"openpyxl","value":"Named tables and formatted export"},{"label":"MSAL · OAuth2","value":"Corporate sign-in"},{"label":"Graph API · Azure","value":"Read and write in SharePoint, deployment"}],"architecture":[{"label":"app.py","value":"Orchestrator and router of the three modules"},{"label":"auth/","value":"Azure AD and SharePoint client"},{"label":"ui/","value":"Settlement, matrix printing, and market file"},{"label":"utils/","value":"Settlement, matrices, export, and file generator"}],"flow":["Loads tariffs, users, spot prices, and matrices from SharePoint.","Validates integrity: duplicate dates by user and energy type.","Summarizes the energy by user before settling.","Generates the type 1 surplus matrix and then the type 2 matrix.","Settles by user: surplus valuation, contribution, public lighting, and total.","Exports to Excel, prints the matrices, and publishes the market file to SharePoint."],"features":[{"title":"Settlement by user","text":"Surplus valuation, contribution, public lighting, and total payable, in an auditable way."},{"title":"Exc1 and Exc2 matrices","text":"Hour-by-hour generation with the energy summary by user."},{"title":"Matrix printing","text":"One sheet per user on the corporate template, with a progress bar for large batches."},{"title":"Market file","text":"Generated in the official format and published to SharePoint by year and month."},{"title":"Integrity validation","text":"Prevents incorrect settlements caused by inconsistent source data."},{"title":"Formatted export","text":"All tables to Excel with currency formatting."}],"screens":[{"title":"Settlement by user","caption":"Period summary and a table with the surplus valuation and the total payable for each user."},{"title":"Market file and annex","caption":"Generation of the official file with its preview, and of the per-user sheets for the invoice."}],"impact":{"stats":[{"value":"~5 min","label":"per settlement, previously more than 12 h"},{"value":"~3 min","label":"for the matrices, previously more than 5 h"},{"value":"~250","label":"users settled per period"},{"value":"3","label":"outputs: settlement, report, and annex"}],"rows":[{"indicator":"Settlement of one period","before":"More than 12 hours, manual in Excel","after":"~5 minutes"},{"indicator":"Hourly matrices per user","before":"More than 5 hours, prone to errors","after":"~3 minutes, uniform format"},{"indicator":"Hour-by-hour calculation","before":"Carry-over errors","after":"Automatic and consistent"},{"indicator":"File for the market","before":"Manual, risk of rejection","after":"Exact format, generated"}],"closing":"It covers end to end the three outputs of the process: the economic settlement, the report to the market, and the document the customer sees. It reduced the risk of error and standardized a process that depended on each analyst's manual care."}}}$copy_1$::jsonb
);

insert into public.projects (
  slug, date, display_order, featured, anonymized, hero, tags, screens, copy
) values (
  'indicadores-saidi-saifi',
  '2026-06',
  2,
  true,
  true,
  'saidi-hero',
  array['Python', 'Streamlit', 'SharePoint', 'Regulación CREG']::text[],
  $screens_2$[{"mock":"saidi-pasos"},{"mock":"saidi-consolidado"}]$screens_2$::jsonb,
  $copy_2${"es":{"title":"Indicadores SAIDI-SAIFI y Formularios SUI","excerpt":"Calcula los indicadores de calidad del servicio de distribución y arma el formulario regulatorio mes a mes.","lead":"Un pipeline de cuatro pasos que va de los archivos diarios de interrupciones al formulario mensual, con una arquitectura de módulos que crece sin tocar el núcleo.","facts":[{"label":"Tipo","value":"Aplicación web interna, modular"},{"label":"Rol","value":"Diseño, desarrollo y puesta en producción"},{"label":"Estado","value":"Módulo SAIDI-SAIFI en producción; los demás formularios, planificados"},{"label":"Marco","value":"CREG 015 de 2018 y formularios del SUI"},{"label":"Stack","value":"Python, Streamlit, Pandas, openpyxl"},{"label":"Integraciones","value":"Azure AD y SharePoint multi-sitio vía Graph API"}],"summary":["Calcula los indicadores de duración (SAIDI) y frecuencia (SAIFI) de las interrupciones de una red de distribución, los consolida por año y genera el formulario mensual que se reporta al regulador.","La aplicación está pensada como una plataforma: cada formulario es un módulo que se descubre solo, con su propio contrato, rutas y servicios, de modo que sumar uno nuevo no exige modificar el núcleo."],"context":{"paragraphs":["La regulación define cómo se mide la calidad del servicio: la duración y la frecuencia de las interrupciones, ponderadas por los usuarios que cuelgan de cada transformador y separadas entre programadas y no programadas. Los datos llegan como archivos diarios, y se deben cruzar con el inventario de transformadores y con el reporte mensual de usuarios.","Cada mes el resultado alimenta un consolidado anual, una tabla histórica y un formulario que se carga a la plataforma del regulador. Hacer esa cadena a mano exige abrir decenas de archivos y repetir cruces que fallan en silencio."],"question":"¿Cuál fue el SAIDI y el SAIFI de este mes, cómo se explican por transformador y cómo se arma el formulario sin errores de arrastre?"},"novelty":"Es una solución específica del reporte regulatorio de un distribuidor: cruza interrupciones, inventario y usuarios, mantiene una tabla histórica por transformador y arma el formulario, todo sobre varios sitios de SharePoint.","challenges":[{"title":"Cálculo ponderado por transformador","text":"SAIDI y SAIFI se calculan por separado para interrupciones programadas y no programadas, ponderando por usuarios, y se suman al final. Una columna de aplicabilidad decide qué eventos entran, según los criterios de exclusión de la norma."},{"title":"Dependencias entre pasos con validación","text":"Cada paso exige los resultados de los anteriores: el formulario necesita el consolidado del año y los pasos 1 y 2 de cada mes hasta el elegido. La aplicación verifica esas dependencias, informa los archivos faltantes y evita generar un formulario incompleto."},{"title":"SharePoint multi-sitio y rutas por periodo","text":"Los insumos viven en sitios distintos y en carpetas por año y mes, con variantes con y sin cero a la izquierda. Un cliente de Graph y un servicio de dominio encapsulan el descubrimiento de rutas, y el Excel maestro con tablas nombradas se actualiza de forma controlada."},{"title":"Arquitectura modular con descubrimiento automático","text":"Cada módulo declara su metadata y expone un contrato único. El enrutador los descubre al arrancar. Se apoya en un tipo de resultado unificado, un almacén de caché genérico y servicios sin estado, así que los módulos pendientes se agregan sin tocar el núcleo."}],"method":["Servicios de dominio sin estado y con resultados tipados (dataclasses), fáciles de probar.","Una sola fuente para las variables de entorno y un mapa documentado de sitios y rutas.","Pruebas automatizadas del módulo de cálculo.","Guías técnicas versionadas (negocio y arquitectura) pensadas para trabajar con asistentes de IA."],"stack":[{"label":"Python 3","value":"Núcleo y servicios de dominio"},{"label":"Streamlit","value":"Interfaz y navegación por módulos"},{"label":"Pandas","value":"Cruces y cálculo de indicadores"},{"label":"openpyxl","value":"Tablas nombradas y formularios"},{"label":"Azure AD · Graph API","value":"Autenticación y SharePoint multi-sitio"},{"label":"PyInstaller","value":"Ejecutable de escritorio opcional"}],"architecture":[{"label":"core/auth","value":"Azure AD y cliente de Graph multi-sitio"},{"label":"core/config","value":"Constantes, ajustes, enrutador y sesión"},{"label":"core/services","value":"Servicio de SharePoint, caché y resultado unificado"},{"label":"modules/…","value":"Un directorio por formulario, con ui, rutas, servicios y almacenes"}],"flow":["Paso 1: lee los archivos diarios y los cruza con el inventario para generar el resumen mensual.","Paso 2: calcula SAIDI y SAIFI por transformador y actualiza la tabla histórica.","Paso 3: consolida el año y actualiza la tabla de indicadores.","Paso 4: genera el formulario mensual con los resultados anteriores."],"features":[{"title":"Resumen del mes","text":"Cruza interrupciones con el inventario y avisa de transformadores nuevos."},{"title":"Cálculo por transformador","text":"SAIDI y SAIFI programados y no programados, con el total del periodo."},{"title":"Consolidado anual","text":"Todos los meses disponibles, con los archivos faltantes a la vista."},{"title":"Formulario del regulador","text":"Generado a partir de los pasos previos y guardado por año."},{"title":"Histórico en el Excel maestro","text":"La tabla de hechos y la de indicadores se actualizan sin pisar lo anterior."},{"title":"Módulos por descubrimiento","text":"Cada formulario nuevo es un directorio con su contrato."}],"screens":[{"title":"Flujo de cuatro pasos","caption":"Cada paso muestra su estado, sus advertencias y qué insumos necesita del anterior."},{"title":"Consolidado anual","caption":"Indicadores por mes, con la comparación entre programadas y no programadas y los archivos faltantes."}],"impact":{"stats":[{"value":"~10 min","label":"por periodo, antes varias horas"},{"value":"4","label":"pasos encadenados y validados"},{"value":"5","label":"formularios previstos en la plataforma"},{"value":"2","label":"sitios de SharePoint integrados"}],"rows":[{"indicator":"Preparación mensual del reporte","before":"Varias horas entre archivos y hojas","after":"~10 minutos"},{"indicator":"Cruce de interrupciones e inventario","before":"Manual, fallas silenciosas","after":"Validado, con advertencias"},{"indicator":"Histórico de indicadores","before":"Copias dispersas","after":"Tabla única en el Excel maestro"}],"closing":"Estandarizó un reporte mensual obligatorio y dejó una base reutilizable: los formularios que faltan se construyen como módulos, con el mismo contrato y las mismas herramientas."}},"en":{"title":"SAIDI-SAIFI Indicators and SUI Forms","excerpt":"Calculates distribution service quality indicators and builds the regulatory form month by month.","lead":"A four-step pipeline that goes from the daily outage files to the monthly form, with a module architecture that grows without touching the core.","facts":[{"label":"Type","value":"Internal web application, modular"},{"label":"Role","value":"Design, development, and production rollout"},{"label":"Status","value":"SAIDI-SAIFI module in production; the other forms, planned"},{"label":"Framework","value":"CREG 015 of 2018 and SUI forms"},{"label":"Stack","value":"Python, Streamlit, Pandas, openpyxl"},{"label":"Integrations","value":"Azure AD and multi-site SharePoint via Graph API"}],"summary":["It calculates the duration (SAIDI) and frequency (SAIFI) indicators of outages on a distribution network, consolidates them by year, and generates the monthly form reported to the regulator.","The application is designed as a platform: each form is a module that discovers itself, with its own contract, routes, and services, so adding a new one does not require modifying the core."],"context":{"paragraphs":["The regulation defines how service quality is measured: the duration and frequency of outages, weighted by the users downstream of each transformer and split between scheduled and unscheduled. The data arrives as daily files, and must be cross-referenced with the transformer inventory and with the monthly user report.","Each month the result feeds an annual consolidation, a historical table, and a form that is uploaded to the regulator's platform. Doing that chain by hand means opening dozens of files and repeating cross-references that fail silently."],"question":"What were this month's SAIDI and SAIFI, how are they explained by transformer, and how is the form built without carry-over errors?"},"novelty":"It is a solution specific to a distributor's regulatory report: it cross-references outages, inventory, and users, keeps a historical table by transformer, and builds the form, all across several SharePoint sites.","challenges":[{"title":"Weighted calculation by transformer","text":"SAIDI and SAIFI are calculated separately for scheduled and unscheduled outages, weighted by users, and summed at the end. An applicability column decides which events are included, according to the regulation's exclusion criteria."},{"title":"Dependencies between steps with validation","text":"Each step requires the results of the previous ones: the form needs the year's consolidation and steps 1 and 2 of each month up to the one selected. The application checks those dependencies, reports the missing files, and avoids generating an incomplete form."},{"title":"Multi-site SharePoint and paths by period","text":"The inputs live on different sites and in folders by year and month, with variants with and without a leading zero. A Graph client and a domain service encapsulate path discovery, and the master Excel with named tables is updated in a controlled way."},{"title":"Modular architecture with automatic discovery","text":"Each module declares its metadata and exposes a single contract. The router discovers them at startup. It relies on a unified result type, a generic cache store, and stateless services, so the pending modules are added without touching the core."}],"method":["Stateless domain services with typed results (dataclasses), easy to test.","A single source for the environment variables and a documented map of sites and paths.","Automated tests of the calculation module.","Versioned technical guides (business and architecture) designed for working with AI assistants."],"stack":[{"label":"Python 3","value":"Core and domain services"},{"label":"Streamlit","value":"Interface and navigation by module"},{"label":"Pandas","value":"Cross-references and indicator calculation"},{"label":"openpyxl","value":"Named tables and forms"},{"label":"Azure AD · Graph API","value":"Authentication and multi-site SharePoint"},{"label":"PyInstaller","value":"Optional desktop executable"}],"architecture":[{"label":"core/auth","value":"Azure AD and multi-site Graph client"},{"label":"core/config","value":"Constants, settings, router, and session"},{"label":"core/services","value":"SharePoint service, cache, and unified result"},{"label":"modules/…","value":"One directory per form, with ui, routes, services, and stores"}],"flow":["Step 1: reads the daily files and cross-references them with the inventory to generate the monthly summary.","Step 2: calculates SAIDI and SAIFI by transformer and updates the historical table.","Step 3: consolidates the year and updates the indicators table.","Step 4: generates the monthly form from the previous results."],"features":[{"title":"Month summary","text":"Cross-references outages with the inventory and flags new transformers."},{"title":"Calculation by transformer","text":"Scheduled and unscheduled SAIDI and SAIFI, with the period total."},{"title":"Annual consolidation","text":"All available months, with the missing files in view."},{"title":"Regulator form","text":"Generated from the previous steps and saved by year."},{"title":"History in the master Excel","text":"The fact table and the indicators table are updated without overwriting what came before."},{"title":"Modules by discovery","text":"Each new form is a directory with its contract."}],"screens":[{"title":"Four-step flow","caption":"Each step shows its status, its warnings, and which inputs it needs from the previous one."},{"title":"Annual consolidation","caption":"Indicators by month, with the comparison between scheduled and unscheduled and the missing files."}],"impact":{"stats":[{"value":"~10 min","label":"per period, previously several hours"},{"value":"4","label":"chained and validated steps"},{"value":"5","label":"forms planned on the platform"},{"value":"2","label":"SharePoint sites integrated"}],"rows":[{"indicator":"Monthly preparation of the report","before":"Several hours across files and sheets","after":"~10 minutes"},{"indicator":"Cross-reference of outages and inventory","before":"Manual, silent failures","after":"Validated, with warnings"},{"indicator":"Indicator history","before":"Scattered copies","after":"A single table in the master Excel"}],"closing":"It standardized a mandatory monthly report and left a reusable base: the remaining forms are built as modules, with the same contract and the same tools."}}}$copy_2$::jsonb
);

insert into public.projects (
  slug, date, display_order, featured, anonymized, hero, tags, screens, copy
) values (
  'cargos-mercado-mayorista',
  '2026-05',
  3,
  false,
  true,
  'mem-hero',
  array['Python', 'Playwright', 'Streamlit', 'ELT']::text[],
  $screens_3$[{"mock":"mem-descarga"},{"mock":"mem-proceso"}]$screens_3$::jsonb,
  $copy_3${"es":{"title":"Cargos del Mercado Mayorista","excerpt":"Automatiza la descarga de cargos publicados por el operador del mercado, su carga a SharePoint y su procesamiento.","lead":"Un flujo ELT en cuatro pasos que automatiza un portal sin API: descarga, carga y procesamiento de los cargos de uso de la red.","facts":[{"label":"Tipo","value":"Aplicación web interna y ejecutable de escritorio"},{"label":"Rol","value":"Diseño, desarrollo y empaquetado"},{"label":"Estado","value":"En uso; los reportes tarifarios completos, pendientes"},{"label":"Marco","value":"CREG 015 de 2018 (cargos del sistema de distribución)"},{"label":"Stack","value":"Python, Streamlit, Playwright, Pandas, openpyxl"},{"label":"Integraciones","value":"Portal del operador del mercado y SharePoint vía Graph API"}],"summary":["Cada mes el operador del mercado publica en su portal los cargos que alimentan la tarifa de energía. Esta aplicación se conecta al portal, lista lo publicado, descarga los archivos del periodo elegido, los sube al SharePoint del equipo y procesa los libros de cargos.","El portal no ofrece API, así que la extracción se hace con un navegador automatizado, y la herramienta se puede usar desde la web o como ejecutable de escritorio."],"context":{"paragraphs":["El equipo de mercado necesitaba tener cada mes los cargos publicados, organizados en SharePoint y listos para calcular tarifas. El proceso era manual: entrar al portal con una cuenta distinta a la corporativa, buscar los archivos, descargarlos uno a uno, renombrarlos y subirlos.","Es un trabajo repetitivo, sin margen de error, y que depende de una sola persona con acceso."],"question":"¿Cómo dejamos cada mes los archivos correctos en el sitio del equipo, sin repetir una tarea manual que no escala?"},"novelty":"Resuelve la extracción de un portal sin API, con dos identidades distintas (la del portal y la corporativa), y entrega el resultado como una herramienta que cualquier usuario puede ejecutar sin instalar un entorno de desarrollo.","challenges":[{"title":"Automatizar un portal sin API","text":"Un navegador controlado con Playwright se conecta al portal, lista las fuentes publicadas y descarga los archivos del periodo elegido, con mensajes claros de estado en cada paso."},{"title":"Dos identidades en el mismo flujo","text":"El portal exige una cuenta Microsoft distinta de la corporativa, que se usa para SharePoint. Las credenciales de cada una se manejan por separado y nunca se incrustan en el código."},{"title":"Ejecutable autocontenido","text":"El empaquetado incluye Streamlit, un lanzador que carga la configuración junto al ejecutable y una carpeta con el navegador. Se distribuye en una carpeta de SharePoint sin instalar Python en cada equipo."},{"title":"Despliegue en la nube con navegador","text":"Correr un navegador automatizado en un hosting gestionado exigió dependencias de sistema, un arranque que instala el navegador en frío y fijar versiones compatibles de las librerías y de Python."}],"method":["Pasos secuenciales con estado visible: cada uno habilita el siguiente.","Un registro de módulos que deja espacio para nuevas funciones sin reescribir la navegación.","Manual de usuario y guía de empaquetado versionados junto al código."],"stack":[{"label":"Python 3","value":"Núcleo y servicios"},{"label":"Streamlit","value":"Interfaz por pasos"},{"label":"Playwright","value":"Navegador automatizado para el portal"},{"label":"Pandas · openpyxl","value":"Procesamiento de los libros de cargos"},{"label":"Azure AD · Graph API","value":"Carga a SharePoint"},{"label":"PyInstaller","value":"Ejecutable de escritorio"}],"architecture":[{"label":"app.py","value":"Orquestador: autenticación, encabezado y enrutador"},{"label":"config/","value":"Constantes, registro de módulos y estilos"},{"label":"ui/","value":"Navegación, enrutador y los cuatro pasos del módulo"},{"label":"services/","value":"Portal, descarga, SharePoint y procesamiento"}],"flow":["Conecta al portal y lista los archivos publicados.","Descarga los del periodo elegido, por tipo de cargo.","Los sube al sitio de SharePoint del equipo.","Procesa los libros de cargos y genera el archivo de salida."],"features":[{"title":"Conexión al portal","text":"Estado visible y listado de lo publicado."},{"title":"Descarga por periodo","text":"Elige el tipo, el año y el mes; una o ambas fuentes."},{"title":"Carga a SharePoint","text":"Con prueba de conexión previa."},{"title":"Procesamiento de cargos","text":"Lectura de los libros y generación del archivo de salida."},{"title":"Ejecutable de escritorio","text":"Para usuarios sin entorno de desarrollo."},{"title":"Despliegue web","text":"Alternativa en la nube con el navegador incluido."}],"screens":[{"title":"Listado y descarga","caption":"Se eligen las fuentes y el periodo, y se marca lo que se va a descargar con el avance de cada archivo."},{"title":"Carga y procesamiento","caption":"Los últimos dos pasos con el estado de la subida a SharePoint y el registro del procesamiento."}],"impact":{"stats":[{"value":"~5 min","label":"por mes, antes ~40 min"},{"value":"4","label":"pasos automatizados"},{"value":"2","label":"tipos de cargo soportados"},{"value":"0","label":"instalaciones de Python en los equipos"}],"rows":[{"indicator":"Obtención mensual de los cargos","before":"~40 minutos, descarga manual","after":"~5 minutos, flujo guiado"},{"indicator":"Orden en SharePoint","before":"Depende de quien suba","after":"Estructura uniforme por periodo"},{"indicator":"Dependencia de una persona","before":"Alta","after":"Cualquier usuario autorizado"}],"closing":"Convirtió una tarea manual y frágil en un flujo guiado y repetible, y dejó la base para los reportes tarifarios que se construyen sobre esos cargos."}},"en":{"title":"Wholesale Market Charges","excerpt":"Automates the download of charges published by the market operator, their upload to SharePoint, and their processing.","lead":"A four-step ELT flow that automates a portal with no API: download, upload, and processing of network-use charges.","facts":[{"label":"Type","value":"Internal web application and desktop executable"},{"label":"Role","value":"Design, development, and packaging"},{"label":"Status","value":"In use; the full tariff reports, pending"},{"label":"Framework","value":"CREG 015 of 2018 (distribution system charges)"},{"label":"Stack","value":"Python, Streamlit, Playwright, Pandas, openpyxl"},{"label":"Integrations","value":"Market operator portal and SharePoint via Graph API"}],"summary":["Each month the market operator publishes on its portal the charges that feed the energy tariff. This application connects to the portal, lists what was published, downloads the files for the chosen period, uploads them to the team's SharePoint, and processes the charge workbooks.","The portal offers no API, so extraction is done with an automated browser, and the tool can be used from the web or as a desktop executable."],"context":{"paragraphs":["The market team needed each month's published charges, organized in SharePoint and ready to calculate tariffs. The process was manual: log in to the portal with an account other than the corporate one, find the files, download them one by one, rename them, and upload them.","It is repetitive work, with no margin for error, and it depends on a single person with access."],"question":"How do we leave the correct files on the team's site each month, without repeating a manual task that does not scale?"},"novelty":"It solves extraction from a portal with no API, with two distinct identities (the portal's and the corporate one), and delivers the result as a tool any user can run without installing a development environment.","challenges":[{"title":"Automating a portal with no API","text":"A browser controlled with Playwright connects to the portal, lists the published sources, and downloads the files for the chosen period, with clear status messages at each step."},{"title":"Two identities in the same flow","text":"The portal requires a Microsoft account different from the corporate one, which is used for SharePoint. The credentials of each are handled separately and are never embedded in the code."},{"title":"Self-contained executable","text":"The package includes Streamlit, a launcher that loads the configuration next to the executable, and a folder with the browser. It is distributed in a SharePoint folder without installing Python on each machine."},{"title":"Cloud deployment with a browser","text":"Running an automated browser on managed hosting required system dependencies, a startup that installs the browser on a cold start, and pinning compatible versions of the libraries and of Python."}],"method":["Sequential steps with visible state: each one enables the next.","A module registry that leaves room for new functions without rewriting the navigation.","User manual and packaging guide versioned alongside the code."],"stack":[{"label":"Python 3","value":"Core and services"},{"label":"Streamlit","value":"Step-by-step interface"},{"label":"Playwright","value":"Automated browser for the portal"},{"label":"Pandas · openpyxl","value":"Processing of the charge workbooks"},{"label":"Azure AD · Graph API","value":"Upload to SharePoint"},{"label":"PyInstaller","value":"Desktop executable"}],"architecture":[{"label":"app.py","value":"Orchestrator: authentication, header, and router"},{"label":"config/","value":"Constants, module registry, and styles"},{"label":"ui/","value":"Navigation, router, and the module's four steps"},{"label":"services/","value":"Portal, download, SharePoint, and processing"}],"flow":["Connects to the portal and lists the published files.","Downloads those for the chosen period, by charge type.","Uploads them to the team's SharePoint site.","Processes the charge workbooks and generates the output file."],"features":[{"title":"Portal connection","text":"Visible status and a listing of what was published."},{"title":"Download by period","text":"Choose the type, the year, and the month; one source or both."},{"title":"Upload to SharePoint","text":"With a prior connection test."},{"title":"Charge processing","text":"Reading of the workbooks and generation of the output file."},{"title":"Desktop executable","text":"For users without a development environment."},{"title":"Web deployment","text":"A cloud alternative with the browser included."}],"screens":[{"title":"Listing and download","caption":"The sources and the period are chosen, and what will be downloaded is marked with each file's progress."},{"title":"Upload and processing","caption":"The last two steps, with the SharePoint upload status and the processing log."}],"impact":{"stats":[{"value":"~5 min","label":"per month, previously ~40 min"},{"value":"4","label":"automated steps"},{"value":"2","label":"supported charge types"},{"value":"0","label":"Python installations on the machines"}],"rows":[{"indicator":"Monthly retrieval of the charges","before":"~40 minutes, manual download","after":"~5 minutes, guided flow"},{"indicator":"Order in SharePoint","before":"Depends on who uploads","after":"Uniform structure by period"},{"indicator":"Dependence on one person","before":"High","after":"Any authorized user"}],"closing":"It turned a manual, fragile task into a guided, repeatable flow, and left the base for the tariff reports built on those charges."}}}$copy_3$::jsonb
);

insert into public.projects (
  slug, date, display_order, featured, anonymized, hero, tags, screens, copy
) values (
  'pipeline-aenc-tfroc',
  '2026-03',
  4,
  false,
  true,
  'aenc-hero',
  array['Python', 'Docker', 'Cron', 'Azure AD']::text[],
  $screens_4$[{"mock":"aenc-registro"},{"mock":"aenc-versiones"}]$screens_4$::jsonb,
  $copy_4${"es":{"title":"Pipeline AENC/TFROC","excerpt":"De una app guiada a un proceso desatendido en Docker: descarga de un FTP, carga a SharePoint y actualización de consumos y demanda.","lead":"El mismo motor de negocio, primero como aplicación con interfaz y luego como proceso diario sin intervención y sin navegador.","facts":[{"label":"Tipo","value":"App guiada y versión desatendida"},{"label":"Rol","value":"Diseño, desarrollo y despliegue"},{"label":"Estado","value":"App en uso; versión desatendida en despliegue"},{"label":"Fuente","value":"Servidor FTP del operador del mercado"},{"label":"Stack","value":"Python, Streamlit, Pandas, Docker, cron"},{"label":"Integraciones","value":"SharePoint vía Graph API, autenticación de aplicación con certificado"}],"summary":["El operador del mercado publica cada día archivos de consumos y de fronteras en un servidor FTP. El proyecto los descarga, los sube a SharePoint, los procesa y actualiza los archivos anuales de consumo y de demanda.","Nació como una aplicación con interfaz de cuatro pasos y evolucionó a una versión desatendida: se ejecuta sola en un contenedor, con una programación diaria, y deja un registro de estado de cada corrida."],"context":{"paragraphs":["Los archivos llegan en varias versiones: preliminares y una final. El mes anterior se reprocesa mientras sigan siendo preliminares y una última vez cuando pasan a final. Seguir ese rastro a mano, cada día y para tres tipos de información, es una fuente constante de errores.","Una vez estable el proceso guiado, el siguiente paso natural era sacar a la persona del medio."],"question":"¿Cómo dejamos que el proceso corra solo cada día, sepa qué versión ya procesó y avise con claridad cuando algo falla?"},"novelty":"Una regla de reprocesamiento por versión con marcador durable, y un motor de negocio reutilizado sin cambios entre una interfaz web y un proceso por lotes.","challenges":[{"title":"Prioridad de versiones y reprocesamiento","text":"Entre las versiones de un archivo gana la final sobre las preliminares. El mes anterior se reprocesa mientras haya preliminares y una vez más al llegar la final. Un marcador durable entre corridas recuerda la última versión procesada."},{"title":"Reutilizar el motor sin la interfaz","text":"El motor de negocio ya estaba desacoplado de la UI. La versión por lotes lo reutiliza y sustituye la capa de Streamlit por un reportero basado en logging, así que no hay dos copias de la lógica."},{"title":"Autenticación sin usuario","text":"La aplicación se autentica a sí misma con un certificado y obtiene un token de aplicación, con permisos limitados y consentimiento de administrador, en lugar de depender del inicio de sesión de una persona."},{"title":"Estado diario y fallo controlado","text":"Cada paso confirma el éxito del anterior y, si una sección falla, la siguiente no corre. Cada corrida deja un archivo de estado, primero local y luego en SharePoint, y termina con un código de salida que dice si todo salió bien."}],"method":["Secciones y pasos con confirmación explícita antes de continuar.","Credenciales que rotan leídas en cada corrida desde un archivo montado, sin reconstruir la imagen.","Guías de despliegue y de configuración de Azure versionadas."],"stack":[{"label":"Python 3","value":"Motor de negocio y orquestador"},{"label":"Pandas","value":"Procesamiento día a día"},{"label":"Streamlit","value":"Interfaz de la versión guiada"},{"label":"Docker · cron","value":"Ejecución programada y desatendida"},{"label":"Graph API","value":"SharePoint con token de aplicación"},{"label":"PyInstaller","value":"Ejecutable de la versión guiada"}],"architecture":[{"label":"run_batch.py","value":"Orquestador y punto de entrada"},{"label":"orchestrator/","value":"Consumos, fronteras y falla/hurto"},{"label":"runtime/","value":"Reportero con logging y estado diario"},{"label":"services/ · utils/","value":"Motor de negocio compartido con la app"}],"flow":["Descarga del FTP y subida a SharePoint, para el mes actual y el anterior.","Procesa los datos de consumo.","Actualiza el archivo anual de consumo y el de demanda.","Actualiza fronteras y falla/hurto, cada una como sección propia.","Escribe el estado del día y termina con su código de salida."],"features":[{"title":"Prioridad de versiones","text":"Final sobre preliminares, con limpieza de lo reemplazado."},{"title":"Tres secciones","text":"Consumos, fronteras y falla/hurto, en orden y con control de errores."},{"title":"Ejecución programada","text":"Cron interno en un contenedor, con corrida manual cuando se necesita."},{"title":"Estado diario","text":"Registro por sección y por paso, local y en SharePoint."},{"title":"Configuración rotativa","text":"Cambiar credenciales no exige reconstruir nada."},{"title":"Versión guiada","text":"La misma lógica con interfaz de cuatro pasos y ejecutable."}],"screens":[{"title":"Registro de una corrida","caption":"Salida del proceso desatendido: cada sección y paso con su resultado y el cierre del día."},{"title":"Versiones y estado del día","caption":"La regla de versiones sobre un mes y el archivo de estado que deja cada corrida."}],"impact":{"stats":[{"value":"3","label":"secciones, 9 pasos encadenados"},{"value":"~30 min","label":"diarios de trabajo manual evitados"},{"value":"0","label":"clics y 0 navegadores"},{"value":"1","label":"motor de negocio para dos versiones"}],"rows":[{"indicator":"Ejecución diaria","before":"Una persona recorre los pasos","after":"Automática, con cron"},{"indicator":"Control de versiones del archivo","before":"Seguimiento manual","after":"Marcador durable por mes"},{"indicator":"Visibilidad del resultado","before":"Se sabe al revisar","after":"Estado diario y código de salida"}],"closing":"Mostró cómo evolucionar una herramienta guiada hacia un proceso desatendido sin duplicar la lógica: el mismo motor, dos formas de ejecutarlo."}},"en":{"title":"AENC/TFROC Pipeline","excerpt":"From a guided app to an unattended process in Docker: download from an FTP, upload to SharePoint, and an update of consumption and demand.","lead":"The same business engine, first as an application with an interface and then as a daily process with no intervention and no browser.","facts":[{"label":"Type","value":"Guided app and unattended version"},{"label":"Role","value":"Design, development, and deployment"},{"label":"Status","value":"App in use; unattended version in deployment"},{"label":"Source","value":"Market operator's FTP server"},{"label":"Stack","value":"Python, Streamlit, Pandas, Docker, cron"},{"label":"Integrations","value":"SharePoint via Graph API, application authentication with a certificate"}],"summary":["Each day the market operator publishes consumption and boundary files on an FTP server. The project downloads them, uploads them to SharePoint, processes them, and updates the annual consumption and demand files.","It started as a four-step interface application and evolved into an unattended version: it runs on its own in a container, on a daily schedule, and leaves a status record of each run."],"context":{"paragraphs":["The files arrive in several versions: preliminary ones and a final one. The previous month is reprocessed while they remain preliminary and one last time when they become final. Following that trail by hand, every day and for three kinds of information, is a constant source of errors.","Once the guided process was stable, the natural next step was to take the person out of the middle."],"question":"How do we let the process run on its own every day, know which version it already processed, and report clearly when something fails?"},"novelty":"A version-based reprocessing rule with a durable marker, and a business engine reused unchanged between a web interface and a batch process.","challenges":[{"title":"Version priority and reprocessing","text":"Among a file's versions, the final one wins over the preliminary ones. The previous month is reprocessed while there are preliminary versions and once more when the final one arrives. A durable marker between runs remembers the last version processed."},{"title":"Reusing the engine without the interface","text":"The business engine was already decoupled from the UI. The batch version reuses it and replaces the Streamlit layer with a logging-based reporter, so there are not two copies of the logic."},{"title":"Authentication without a user","text":"The application authenticates itself with a certificate and obtains an application token, with limited permissions and administrator consent, instead of depending on a person's sign-in."},{"title":"Daily status and controlled failure","text":"Each step confirms the success of the previous one and, if a section fails, the next one does not run. Each run leaves a status file, first locally and then in SharePoint, and ends with an exit code that says whether everything went well."}],"method":["Sections and steps with explicit confirmation before continuing.","Rotating credentials read on each run from a mounted file, without rebuilding the image.","Versioned deployment and Azure configuration guides."],"stack":[{"label":"Python 3","value":"Business engine and orchestrator"},{"label":"Pandas","value":"Day-by-day processing"},{"label":"Streamlit","value":"Interface of the guided version"},{"label":"Docker · cron","value":"Scheduled, unattended execution"},{"label":"Graph API","value":"SharePoint with an application token"},{"label":"PyInstaller","value":"Executable of the guided version"}],"architecture":[{"label":"run_batch.py","value":"Orchestrator and entry point"},{"label":"orchestrator/","value":"Consumption, boundaries, and failure/theft"},{"label":"runtime/","value":"Reporter with logging and daily status"},{"label":"services/ · utils/","value":"Business engine shared with the app"}],"flow":["FTP download and upload to SharePoint, for the current month and the previous one.","Processes the consumption data.","Updates the annual consumption file and the demand file.","Updates boundaries and failure/theft, each as its own section.","Writes the day's status and finishes with its exit code."],"features":[{"title":"Version priority","text":"Final over preliminary, with cleanup of what was replaced."},{"title":"Three sections","text":"Consumption, boundaries, and failure/theft, in order and with error control."},{"title":"Scheduled execution","text":"Internal cron in a container, with a manual run when needed."},{"title":"Daily status","text":"A record by section and by step, locally and in SharePoint."},{"title":"Rotating configuration","text":"Changing credentials does not require rebuilding anything."},{"title":"Guided version","text":"The same logic with a four-step interface and an executable."}],"screens":[{"title":"Log of a run","caption":"Output of the unattended process: each section and step with its result and the close of the day."},{"title":"Versions and the day's status","caption":"The version rule over a month and the status file each run leaves behind."}],"impact":{"stats":[{"value":"3","label":"sections, 9 chained steps"},{"value":"~30 min","label":"of daily manual work avoided"},{"value":"0","label":"clicks and 0 browsers"},{"value":"1","label":"business engine for two versions"}],"rows":[{"indicator":"Daily execution","before":"A person walks through the steps","after":"Automatic, with cron"},{"indicator":"File version control","before":"Manual tracking","after":"Durable marker by month"},{"indicator":"Visibility of the result","before":"Known when it is reviewed","after":"Daily status and exit code"}],"closing":"It showed how to evolve a guided tool into an unattended process without duplicating the logic: the same engine, two ways to run it."}}}$copy_4$::jsonb
);

insert into public.projects (
  slug, date, display_order, featured, anonymized, hero, tags, screens, copy
) values (
  'ai-radar',
  '2026-05',
  5,
  false,
  false,
  'radar-hero',
  array['Node.js', 'Supabase', 'Vercel', 'Playwright']::text[],
  $screens_5$[{"mock":"radar-senal"},{"mock":"radar-historial"}]$screens_5$::jsonb,
  $copy_5${"es":{"title":"AI Radar","excerpt":"Convierte el ruido de noticias, repos y papers de IA en cinco señales diarias accionables, con API y dashboard.","lead":"Un radar diario que separa lo que importa del ruido: qué pasó, por qué importa, qué tan confiable es y qué vale la pena probar.","facts":[{"label":"Tipo","value":"Proyecto personal, curso avanzado de Codex"},{"label":"Rol","value":"Producto, diseño y desarrollo"},{"label":"Estado","value":"En construcción por capas"},{"label":"Stack","value":"Node.js 24, Supabase (Postgres), Vercel Functions"},{"label":"Calidad","value":"Pruebas de dominio con node:test y E2E con Playwright"}],"summary":["AI Radar organiza noticias, herramientas, papers, repos y lanzamientos de IA para convertirlos en señales accionables para quien construye producto: qué ocurrió, por qué importa, qué tan confiable es y qué conviene probar.","Cada día se guarda una captura de exactamente cinco señales con su contexto y fuentes, y un dashboard la consulta a través de una API propia."],"context":{"paragraphs":["El ritmo de la IA genera demasiado ruido: lanzamientos repetidos en varias fuentes, repos que parecen importantes pero no tienen adopción, demos sin documentación y herramientas con impacto real mezcladas con marketing."],"question":"¿Qué pasó hoy en IA que realmente vale la pena probar, y con qué evidencia?"},"novelty":"Un producto con contrato de datos explícito: un JSON Schema valida cada captura y la escritura reemplaza el día completo de forma atómica, de modo que nunca quedan datos a medias.","challenges":[{"title":"Contrato de datos validado","text":"Cada captura diaria se valida con un esquema y comprobaciones de fechas, identificadores, URLs y etiquetas, y se exigen exactamente cinco señales. Existen fixtures y un script de validación."},{"title":"Escritura idempotente y atómica","text":"Una captura reemplaza por completo las señales y fuentes del día, de modo que repetir la importación produce el mismo resultado. Un modo de ensayo muestra qué cambiaría antes de escribir."},{"title":"Permisos separados y secretos en el servidor","text":"Hay un token de lectura y otro de escritura, distintos. El navegador nunca recibe secretos: las funciones del dashboard los inyectan desde el entorno del servidor. La base usa RLS sin acceso para roles públicos."},{"title":"Sin respaldo silencioso","text":"El dashboard usa solo la API real y falla de forma explícita si la base no responde; no cae a datos locales. Una prueba E2E verifica que la API real carga las cinco señales en el navegador."}],"method":["Se construye por capas: dominio, aplicación e infraestructura separados.","Reglas de trabajo para agentes de IA versionadas junto al código.","Despliegue sin paso de compilación: frontend estático y funciones en Vercel."],"stack":[{"label":"Node.js 24","value":"Dominio, scripts y API"},{"label":"Supabase","value":"Postgres con RLS"},{"label":"Vercel","value":"Frontend estático y Functions"},{"label":"Ajv","value":"Validación con JSON Schema"},{"label":"Playwright","value":"Pruebas de extremo a extremo"}],"architecture":[{"label":"src/","value":"Dominio, aplicación e infraestructura"},{"label":"api/","value":"Vercel Functions con los adaptadores"},{"label":"data/contracts/","value":"Esquema JSON de la captura diaria"},{"label":"scripts/","value":"Importación, validación y consulta"},{"label":"supabase/","value":"Migraciones reproducibles"}],"flow":["Se genera la captura del día con cinco señales.","Se valida contra el esquema.","Se importa en modo ensayo y luego se aplica.","La API sirve las capturas y señales con el token de lectura.","El dashboard muestra el día o una fecha histórica."],"features":[{"title":"Cinco señales al día","text":"Ordenadas por novedad, impacto, evidencia y accionabilidad."},{"title":"Historial","text":"Consulta de hasta 100 capturas persistidas."},{"title":"Guía práctica","text":"Qué vale la pena probar y por qué."},{"title":"API con permisos","text":"Rutas de lectura y de escritura con tokens separados."},{"title":"Importación segura","text":"Ensayo previo y verificación de paridad al aplicar."},{"title":"Dashboard","text":"Selector de periodo sobre la API real."}],"screens":[{"title":"Detalle de una señal","caption":"Qué pasó, por qué importa, qué tan confiable es la evidencia y qué conviene probar."},{"title":"Historial y estado de la API","caption":"Selector de capturas persistidas y el estado de las rutas de lectura y escritura."}],"impact":{"stats":[{"value":"5","label":"señales por captura diaria"},{"value":"100","label":"capturas consultables"},{"value":"2","label":"tokens con permisos separados"},{"value":"E2E","label":"con la API real en el navegador"}],"rows":[{"indicator":"Lectura diaria de novedades","before":"Decenas de fuentes y duplicados","after":"Cinco señales con contexto"},{"indicator":"Calidad del dato","before":"Sin contrato","after":"Esquema validado y escritura atómica"},{"indicator":"Secretos en el navegador","before":"—","after":"Ninguno"}],"closing":"Es un proyecto en marcha: lo que ya existe es el contrato de datos, la persistencia y la API con su dashboard, y el trabajo siguiente es la recopilación y el ranking automático de fuentes."}},"en":{"title":"AI Radar","excerpt":"Turns the noise of AI news, repos, and papers into five actionable daily signals, with an API and a dashboard.","lead":"A daily radar that separates what matters from the noise: what happened, why it matters, how reliable it is, and what is worth trying.","facts":[{"label":"Type","value":"Personal project, advanced Codex course"},{"label":"Role","value":"Product, design, and development"},{"label":"Status","value":"Being built in layers"},{"label":"Stack","value":"Node.js 24, Supabase (Postgres), Vercel Functions"},{"label":"Quality","value":"Domain tests with node:test and E2E with Playwright"}],"summary":["AI Radar organizes AI news, tools, papers, repos, and launches and turns them into actionable signals for whoever builds product: what happened, why it matters, how reliable it is, and what is worth trying.","Each day a capture of exactly five signals is stored with its context and sources, and a dashboard queries it through its own API."],"context":{"paragraphs":["The pace of AI generates too much noise: launches repeated across several sources, repos that look important but have no adoption, demos without documentation, and tools with real impact mixed in with marketing."],"question":"What happened in AI today that is actually worth trying, and with what evidence?"},"novelty":"A product with an explicit data contract: a JSON Schema validates each capture and the write replaces the entire day atomically, so data is never left half-written.","challenges":[{"title":"Validated data contract","text":"Each daily capture is validated with a schema and checks on dates, identifiers, URLs, and tags, and exactly five signals are required. There are fixtures and a validation script."},{"title":"Idempotent, atomic write","text":"A capture completely replaces the day's signals and sources, so repeating the import produces the same result. A dry-run mode shows what would change before writing."},{"title":"Separate permissions and secrets on the server","text":"There is a read token and a write token, and they are distinct. The browser never receives secrets: the dashboard functions inject them from the server environment. The database uses RLS with no access for public roles."},{"title":"No silent fallback","text":"The dashboard uses only the real API and fails explicitly if the database does not respond; it does not fall back to local data. An E2E test verifies that the real API loads the five signals in the browser."}],"method":["It is built in layers: domain, application, and infrastructure kept separate.","Working rules for AI agents, versioned alongside the code.","Deployment with no build step: a static frontend and functions on Vercel."],"stack":[{"label":"Node.js 24","value":"Domain, scripts, and API"},{"label":"Supabase","value":"Postgres with RLS"},{"label":"Vercel","value":"Static frontend and Functions"},{"label":"Ajv","value":"Validation with JSON Schema"},{"label":"Playwright","value":"End-to-end tests"}],"architecture":[{"label":"src/","value":"Domain, application, and infrastructure"},{"label":"api/","value":"Vercel Functions with the adapters"},{"label":"data/contracts/","value":"JSON schema of the daily capture"},{"label":"scripts/","value":"Import, validation, and query"},{"label":"supabase/","value":"Reproducible migrations"}],"flow":["The day's capture is generated with five signals.","It is validated against the schema.","It is imported in dry-run mode and then applied.","The API serves the captures and signals with the read token.","The dashboard shows the day or a historical date."],"features":[{"title":"Five signals a day","text":"Ordered by novelty, impact, evidence, and actionability."},{"title":"History","text":"Query of up to 100 persisted captures."},{"title":"Practical guide","text":"What is worth trying and why."},{"title":"API with permissions","text":"Read and write routes with separate tokens."},{"title":"Safe import","text":"A prior dry run and a parity check when applying."},{"title":"Dashboard","text":"Period selector over the real API."}],"screens":[{"title":"Signal detail","caption":"What happened, why it matters, how reliable the evidence is, and what is worth trying."},{"title":"History and API status","caption":"Selector of persisted captures and the status of the read and write routes."}],"impact":{"stats":[{"value":"5","label":"signals per daily capture"},{"value":"100","label":"queryable captures"},{"value":"2","label":"tokens with separate permissions"},{"value":"E2E","label":"with the real API in the browser"}],"rows":[{"indicator":"Daily reading of what's new","before":"Dozens of sources and duplicates","after":"Five signals with context"},{"indicator":"Data quality","before":"No contract","after":"Validated schema and atomic write"},{"indicator":"Secrets in the browser","before":"—","after":"None"}],"closing":"It is a project in progress: what already exists is the data contract, the persistence, and the API with its dashboard, and the next work is the collection and automatic ranking of sources."}}}$copy_5$::jsonb
);
